import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:intl/intl.dart';
import 'package:shared_preferences/shared_preferences.dart';

const base='https://lendix-be-420077667925.us-central1.run.app';
const purple=Color(0xff6846f5), mint=Color(0xff2bc79b);
String money(dynamic v)=>'S/ ${NumberFormat('#,##0','es_PE').format((num.tryParse('$v')??0).round())}';
class Api{final String auth;Api(this.auth);Future<dynamic> get(String p)async{final r=await http.get(Uri.parse('$base$p'),headers:{'Authorization':'Basic $auth'});if(r.statusCode>299)throw Exception('Error ${r.statusCode}: ${r.body}');return jsonDecode(r.body);}Future<dynamic> post(String p,Map<String,dynamic> b)async{final r=await http.post(Uri.parse('$base$p'),headers:{'Authorization':'Basic $auth','Content-Type':'application/json'},body:jsonEncode(b));if(r.statusCode>299)throw Exception('Error ${r.statusCode}: ${r.body}');return jsonDecode(r.body);}}
Future<void> alert(BuildContext c,String t,String m)=>showDialog(context:c,builder:(_)=>AlertDialog(title:Text(t),content:Text(m),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Aceptar'))]));
void main()=>runApp(const App());
class App extends StatefulWidget{const App({super.key});@override State<App> createState()=>_AppState();}
class _AppState extends State<App>{Api? api;@override void initState(){super.initState();SharedPreferences.getInstance().then((p){final a=p.getString('auth');if(a!=null)setState(()=>api=Api(a));});}void login(String a)async{final p=await SharedPreferences.getInstance();await p.setString('auth',a);setState(()=>api=Api(a));}void logout()async{final p=await SharedPreferences.getInstance();await p.remove('auth');setState(()=>api=null);}@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:purple),scaffoldBackgroundColor:const Color(0xfff6f7fb)),home:api==null?Login(onLogin:login):Shell(api:api!,logout:logout));}
class Login extends StatefulWidget{final void Function(String) onLogin;const Login({super.key,required this.onLogin});@override State<Login> createState()=>_LoginState();}
class _LoginState extends State<Login>{final u=TextEditingController(text:'admin'),p=TextEditingController(text:'Admin123@');bool hide=true,busy=false;Future<void> go()async{if(u.text.isEmpty||p.text.isEmpty){alert(context,'Validación','Usuario y contraseña son obligatorios.');return;}setState(()=>busy=true);final a=base64Encode(utf8.encode('${u.text.trim()}:${p.text}'));try{await Api(a).get('/api/v1/dashboard');widget.onLogin(a);}catch(e){if(mounted)alert(context,'No se pudo iniciar sesión','$e');}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const CircleAvatar(radius:28,backgroundColor:mint,child:Text('L',style:TextStyle(fontSize:30))),const SizedBox(height:18),const Text('Accede a tu cartera',style:TextStyle(fontSize:27,fontWeight:FontWeight.bold)),const SizedBox(height:18),TextField(controller:u,decoration:const InputDecoration(labelText:'Usuario',prefixIcon:Icon(Icons.person_outline))),const SizedBox(height:12),TextField(controller:p,obscureText:hide,decoration:InputDecoration(labelText:'Contraseña',prefixIcon:const Icon(Icons.lock_outline),suffixIcon:IconButton(onPressed:()=>setState(()=>hide=!hide),icon:Icon(hide?Icons.visibility:Icons.visibility_off)))),const SizedBox(height:18),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:busy?null:go,icon:busy?const SizedBox(width:18,height:18,child:CircularProgressIndicator(color:Colors.white)):const Icon(Icons.login),label:Text(busy?'Validando…':'Entrar')))]))))));}
class Shell extends StatefulWidget{final Api api;final VoidCallback logout;const Shell({super.key,required this.api,required this.logout});@override State<Shell> createState()=>_ShellState();}
class _ShellState extends State<Shell>{ int index=0; final titles=["Resumen","Clientes","Préstamos","Pagos","Reportes"]; Widget page(){ if(index==0)return Dash(api:widget.api); if(index==1)return DataPage(api:widget.api,path:"/api/v1/customers?includeInactive=true",title:"Clientes",icon:Icons.people_outline); if(index==2)return DataPage(api:widget.api,path:"/api/v1/loans?status=ACTIVE",title:"Préstamos",icon:Icons.account_balance_wallet_outlined); if(index==3)return DataPage(api:widget.api,path:"/api/v1/payments",title:"Pagos",icon:Icons.payments_outlined); return Reports(api:widget.api); } @override Widget build(BuildContext c){ return Scaffold(appBar:AppBar(title:Text(titles[index]),actions:[IconButton(onPressed:widget.logout,icon:const Icon(Icons.logout))]),body:page(),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(x)=>setState(()=>index=x),destinations:titles.map((x)=>NavigationDestination(icon:const Icon(Icons.circle_outlined),label:x)).toList())); }}
class Frame extends StatelessWidget{final String title,sub;final Widget child;const Frame({super.key,required this.title,required this.sub,required this.child});@override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:()=>Future.delayed(const Duration(milliseconds:300)),child:ListView(padding:const EdgeInsets.all(16),children:[Text(title,style:const TextStyle(fontSize:30,fontWeight:FontWeight.bold)),Text(sub,style:const TextStyle(color:Colors.grey)),const SizedBox(height:18),child]));}
class Dash extends StatelessWidget{final Api api;const Dash({super.key,required this.api});@override Widget build(BuildContext c)=>FutureBuilder(future:api.get('/api/v1/dashboard'),builder:(_,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Text('${s.error}');final d=s.data as Map;return Frame(title:'Buenos días 👋',sub:'Tu cartera, clara y bajo control.',child:Wrap(spacing:10,runSpacing:10,children:[card('Capital',money(d['capitalPlaced']??0),Icons.trending_up),card('Por cobrar',money(d['outstanding']??0),Icons.pending_actions),card('Clientes','${d['customers']??0}',Icons.people_outline),card('Activos','${d['activeLoans']??0}',Icons.account_balance_wallet_outlined)]));});}
Widget card(String t,String v,IconData i)=>SizedBox(width:160,child:Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(i,color:purple),const SizedBox(height:8),Text(v,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:20)),Text(t,style:const TextStyle(color:Colors.grey))]))));
class DataPage extends StatelessWidget {
  final Api api; final String path, title; final IconData icon;
  const DataPage({super.key, required this.api, required this.path, required this.title, required this.icon});
  @override Widget build(BuildContext context) {
    return Frame(title: title, sub: 'Información sincronizada con tu cartera.', child: FutureBuilder(
      future: api.get(path),
      builder: (_, snapshot) {
        if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator());
        if (snapshot.hasError) return Text('${snapshot.error}');
        final rows = (snapshot.data as List?) ?? [];
        return Card(child: ListView.builder(shrinkWrap: true, itemCount: rows.length, itemBuilder: (_, index) {
          final item = rows[index] as Map;
          return ListTile(leading: CircleAvatar(child: Icon(icon)), title: Text('${item['fullName'] ?? item['customerName'] ?? 'Registro'}'), subtitle: Text('${item['dni'] ?? item['status'] ?? ''}'));
        }));
      },
    ));
  }
}
class Reports extends StatelessWidget{final Api api;const Reports({super.key,required this.api});@override Widget build(BuildContext c)=>Frame(title:'Reportes',sub:'Genera información para compartir.',child:Column(children:[report(c,'Reporte general','/api/v1/reports/portfolio.pdf'),report(c,'Reporte de pagos','/api/v1/reports/payments.pdf')]));Widget report(BuildContext c,String t,String p)=>Card(child:ListTile(leading:const Icon(Icons.picture_as_pdf_outlined,color:purple),title:Text(t),trailing:IconButton(tooltip:'Descargar reporte',icon:const Icon(Icons.download),onPressed:()=>alert(c,'Reporte','Disponible en el backend: $p'))));}
